export type ExteriorView = "arrival" | "facade"

export type ExteriorImage = {
  id: string
  width: number
  height: number
  src: string
  avifSrcSet?: string
  webpSrcSet?: string
  alt: string
}

/**
 * Facade-only registration supplied by the integration owner, not generated by
 * this viewport. Both axes use the exact facade image's normalized 0–1 space.
 * `zoom` is a multiplier of the viewport's cover scale, not an absolute scale.
 * Omit list-only/unapproved floors entirely; never supply a guessed focus.
 */
export type ExteriorBand = {
  id: string
  label: string
  polygons: readonly (readonly (readonly [number, number])[])[]
  focus: readonly [number, number]
  zoom: number
}

/**
 * A snapshot, not a URL or a 3D camera. Image pixel (u,v) projects to viewport
 * CSS pixel (x + u * scale, y + v * scale), measured from its top-left corner.
 * x/y are pan in CSS pixels; scale is CSS pixels per intrinsic image pixel;
 * zoom is scale / coverScale. viewId is the caller's exact image identifier.
 * Dimensions are image/viewport pixels, NEVER architectural measurements.
 *
 * getPose() may return moving=true during a tween, drag or crossfade.
 * onSettled receives moving=false only after the requested still has loaded,
 * its crossfade and camera have completed, and the viewport has nonzero size.
 * Consumers must retain their own selected-floor/source-version context.
 */
export type ExteriorPose = Readonly<{
  view: ExteriorView
  viewId: string
  imageWidth: number
  imageHeight: number
  viewportWidth: number
  viewportHeight: number
  x: number
  y: number
  scale: number
  zoom: number
  moving: boolean
}>

export type ExteriorViewportHandle = {
  /** Restore the current still's scene-specific default, without changing selection or URL. */
  reset(): void
  zoom(direction: 1 | -1): void
  /** null until the requested image is ready and its viewport can be measured. */
  getPose(): ExteriorPose | null
}

export type ExteriorViewportProps = {
  images: { arrival: ExteriorImage; facade: ExteriorImage }
  bands: readonly ExteriorBand[]
  view: ExteriorView
  selectedFloorId: string | null
  hoveredFloorId: string | null
  onFloorSelect: (id: string) => void
  onFloorHover: (id: string | null) => void
  onSettled?: (pose: ExteriorPose) => void
}
// Match the uncropped 16:9 cover-fit plane rather than the narrow portrait viewport.
export const EXTERIOR_IMAGE_SIZES = "(max-width: 700px) max(100vw, calc(177.78svh - 16rem)), max(100vw, 177.78svh)"
